import React from 'react'

const About = () => {
  return (
    <div style={{ padding: '100px 0', textAlign: 'center' }}>
      <h1>Về Chúng Tôi</h1>
      <p>Chào mừng bạn đến với trang web du lịch của chúng tôi!</p>
    </div>
  )
}

export default About
